<section class="projects-section"><div class="section-heading row"><div><p class="eyebrow dark">SELECTED WORK</p><h2>Featured Projects</h2></div><a class="text-link" href="<?=e(site_url('/projects'))?>">VIEW ALL PROJECTS →</a></div><?php if($featured):?><div class="project-grid"><?php foreach(array_slice($featured,0,6) as $p):$img=$p['featured_image']??$p['images'][0]??'';?><a class="project-card" href="<?=e(site_url('/project/'.urlencode($p['slug'])))?>"><div class="project-image"><?php if($img):?><img loading="lazy" src="<?=e(image_url($img))?>" alt="<?=e($p['name'])?>"><?php endif;?></div><div><small><?=e($p['category']??'PROJECT')?></small><h3><?=e($p['name'])?></h3><p><?=e($p['location']??'')?></p></div></a><?php endforeach;?></div><?php else:?><div class="empty-projects"><h3>Your work belongs here.</h3><p>Upload jobs and photos from the admin dashboard.</p></div><?php endif;?></section>